function isIsomorphic(s: string, t: string): boolean {
  // Отображения в обе стороны: s -> t и t -> s
  const sToT = new Map<string, string>();
  const tToS = new Map<string, string>();

  for (let i = 0; i < s.length; i++) {
    const a = s[i];
    const b = t[i];

    const mappedA = sToT.get(a);
    const mappedB = tToS.get(b);

    // Символ a уже отображается во что-то другое — противоречие
    if (mappedA !== undefined && mappedA !== b) return false;
    // В символ b уже отображается другой символ — нарушена взаимность
    if (mappedB !== undefined && mappedB !== a) return false;

    // Запоминаем пару (повторная запись той же пары безвредна)
    sToT.set(a, b);
    tToS.set(b, a);
  }

  return true;
}

// Время: O(n)
// Память: O(k), где k — размер алфавита (не больше 128 для ASCII)
